CAT = "dethBetrieb"; SEG = "BET"
# Vorschriften über den Betrieb der Fahrzeuge.
Q = [
("Welche Papiere müssen Sie beim Fahren mit dem eigenen Pkw immer mitführen?",
 "Führerschein und Zulassungsbescheinigung Teil I", ["Nur die Zulassungsbescheinigung Teil II", "Kaufvertrag und Versicherungsschein des Fahrzeugs", "Personalausweis und Steuerbescheid"],
 "Führerschein und Zulassungsbescheinigung Teil I (Fahrzeugschein) sind mitzuführen und auf Verlangen auszuhändigen. Teil II (Fahrzeugbrief) bleibt zu Hause."),
("In welchem Abstand muss ein privater Pkw regelmäßig zur Hauptuntersuchung?",
 "Alle 2 Jahre", ["Jedes Jahr", "Alle 3 Jahre", "Alle 4 Jahre"],
 "Nach § 29 StVZO und Anlage VIII müssen Pkw alle 24 Monate zur Hauptuntersuchung. Neuwagen kommen erstmals nach 36 Monaten an die Reihe."),
("Welche Ausrüstung muss in einem Pkw mitgeführt werden?",
 "Warndreieck, Verbandkasten und Warnweste", ["Feuerlöscher, Abschleppseil und Wagenheber", "Reservekanister und Wagenheber", "Schneeketten und Taschenlampe"],
 "Warndreieck, Verbandkasten und mindestens eine Warnweste sind nach der StVZO vorgeschrieben."),
("Was gilt für die Ladung in Ihrem Pkw?",
 "Sie muss auch bei Vollbremsung sicher bleiben", ["Sie darf nur unter 50 kg wiegen", "Sie muss nur bei Fahrten über 50 km gesichert werden", "Sie darf auf dem Beifahrersitz lose liegen"],
 "§ 22 Abs. 1 StVO: Ladung ist so zu verstauen und zu sichern, dass sie selbst bei Vollbremsung oder plötzlicher Ausweichbewegung nicht verrutscht oder herabfällt."),
("Ihre Ladung ragt mehr als 1 m nach hinten über das Fahrzeug hinaus. Wie müssen Sie sie kenntlich machen?",
 "Mit einer hellroten Fahne oder Tafel", ["Mit eingeschaltetem Warnblinklicht", "Mit einem weißen Tuch", "Gar nicht, wenn es hell ist"],
 "§ 22 Abs. 4 StVO: Ragt die Ladung mehr als 1 m nach hinten hinaus, ist das Ende durch eine hellrote Fahne, ein Schild oder einen Zylinder kenntlich zu machen."),
("Bis zu welchem Alter oder welcher Größe brauchen Kinder im Auto einen Kindersitz?",
 "Bis 12 Jahre oder 150 cm Größe", ["Bis 6 Jahre oder 120 cm Größe", "Bis 10 Jahre oder 140 cm Größe", "Bis 14 Jahre oder 160 cm Größe"],
 "§ 21 Abs. 1a StVO: Kinder unter 12 Jahren, die kleiner als 150 cm sind, müssen in einer geeigneten Rückhalteeinrichtung gesichert werden."),
("Sie wollen ein Baby in einem rückwärtsgerichteten Kindersitz auf dem Beifahrersitz befördern. Was ist Pflicht?",
 "Den Beifahrer-Airbag abschalten", ["Den Sitz ganz nach vorn schieben", "Das Kind zusätzlich anschnallen", "Den Gurt locker lassen"],
 "Ein auslösender Airbag kann ein Kind im rückwärtsgerichteten Sitz schwer verletzen. Der Beifahrer-Airbag muss dann deaktiviert sein."),
("Wer ist dafür verantwortlich, dass Kinder im Auto richtig gesichert sind?",
 "Die Person am Steuer", ["Allein die Eltern", "Der Halter des Fahrzeugs", "Das Kind selbst ab 10 Jahren"],
 "Der Fahrer muss dafür sorgen, dass mitfahrende Kinder vorschriftsmäßig gesichert sind, auch wenn er nicht Elternteil ist."),
("Bei Schneeglätte wollen Sie mit dem Pkw fahren. Welche Reifen sind Pflicht?",
 "Reifen mit Alpine-Symbol", ["Reifen nur mit M+S-Kennung", "Sommerreifen mit 4 mm Profil", "Ganzjahresreifen ohne Kennzeichnung"],
 "§ 2 Abs. 3a StVO: Bei Glatteis, Schneeglätte, Schneematsch, Eisglätte oder Reifglätte sind Reifen mit dem Alpine-Symbol (Bergpiktogramm mit Schneeflocke) vorgeschrieben. Reifen nur mit M+S genügen seit Oktober 2024 nicht mehr."),
("Welche Fahrzeuge dürfen Sie mit der Fahrerlaubnis der Klasse B fahren?",
 "Kfz bis 3.500 kg zulässige Gesamtmasse", ["Kfz bis 7.500 kg zulässige Gesamtmasse", "Busse mit bis zu 16 Sitzplätzen", "Alle Kfz ohne jede Gewichtsgrenze"],
 "Klasse B gilt für Kraftfahrzeuge bis 3.500 kg zulässige Gesamtmasse mit höchstens acht Sitzplätzen außer dem Fahrersitz."),
("Wie schwer darf ein Anhänger mit Klasse B immer sein, unabhängig vom Zugfahrzeug?",
 "Bis 750 kg zulässige Gesamtmasse", ["Bis 1.000 kg zulässige Gesamtmasse", "Bis 1.500 kg zulässige Gesamtmasse", "Bis 3.500 kg zulässige Gesamtmasse"],
 "Anhänger bis 750 kg zulässige Gesamtmasse dürfen immer mitgeführt werden. Schwerere nur, wenn der Zug insgesamt 3.500 kg nicht übersteigt."),
("Sie schleppen ein liegengebliebenes Auto ab. Was müssen beide Fahrzeuge einschalten?",
 "Das Warnblinklicht", ["Die Nebelschlussleuchte", "Das Fernlicht", "Den rechten Blinker"],
 "§ 15a Abs. 3 StVO: Beim Abschleppen haben beide Fahrzeuge das Warnblinklicht einzuschalten."),
("Sie schleppen ein auf der Autobahn liegengebliebenes Fahrzeug ab. Wo müssen Sie die Autobahn verlassen?",
 "An der nächsten Ausfahrt", ["Erst am Ziel der Fahrt", "Am nächsten Parkplatz", "Nach höchstens 50 km"],
 "§ 15a Abs. 1 StVO: Beim Abschleppen eines auf der Autobahn liegengebliebenen Fahrzeugs ist die Autobahn an der nächsten Ausfahrt zu verlassen."),
("Wer ist während der Fahrt für den vorschriftsmäßigen Zustand des Fahrzeugs verantwortlich?",
 "Die Person am Steuer", ["Nur die Werkstatt", "Nur der Hersteller", "Nur der Halter"],
 "§ 23 Abs. 1 StVO: Wer fährt, ist dafür verantwortlich, dass Fahrzeug, Ladung und Besetzung vorschriftsmäßig sind und die Sicherheit nicht leidet."),
]
